import net from "net";
import { pEvent } from "p-event";
export async function connectAndWaitConnected(opts) {
    const sock = net.connect(opts);
    try {
        await pEvent(sock, "connect", { timeout: opts.connectTimeout ?? 10000 });
    }
    catch (err) {
        sock.destroy();
        throw err;
    }
    sock.on("error", () => undefined);
    return sock;
}
